import sys

sys.setrecursionlimit(1000000)


def evaluate(expr: str) -> float:
    tokens = _tokenize(expr)
    parser = _Parser(tokens)
    value = parser.parse_expression()

    if parser.index != len(parser.tokens):
        raise ValueError("malformed expression")

    try:
        if isinstance(value, complex):
            if value.imag == 0:
                value = value.real
            else:
                raise ValueError("expression evaluates to a non-real value")

        return float(value)
    except TypeError as exc:
        raise ValueError("expression does not evaluate to a float") from exc


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.index = 0

    def _peek(self):
        if self.index < len(self.tokens):
            return self.tokens[self.index]
        return None

    def _peek_value(self):
        token = self._peek()
        if token is None:
            return None
        return token[1]

    def _consume(self, expected=None):
        token = self._peek()
        if token is None:
            raise ValueError("unexpected end of expression")
        if expected is not None and token[1] != expected:
            raise ValueError(f"unexpected token {token[1]!r}")
        self.index += 1
        return token

    def parse_expression(self):
        value = self.parse_term()

        while self._peek_value() in ("+", "-"):
            op = self._consume()[1]
            right = self.parse_term()
            if op == "+":
                value += right
            else:
                value -= right

        return value

    def parse_term(self):
        value = self.parse_factor()

        while self._peek_value() in ("*", "/"):
            op = self._consume()[1]
            right = self.parse_factor()
            if op == "*":
                value *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                value /= right

        return value

    def parse_factor(self):
        value = self._peek_value()

        if value in ("+", "-"):
            op = self._consume()[1]
            operand = self.parse_factor()
            return -operand if op == "-" else operand

        return self.parse_power()

    def parse_power(self):
        value = self.parse_atom()

        if self._peek_value() == "**":
            self._consume()
            exponent = self.parse_factor()
            return _power(value, exponent)

        return value

    def parse_atom(self):
        token = self._peek()
        if token is None:
            raise ValueError("unexpected end of expression")

        kind, value = token

        if kind == "num":
            self.index += 1
            return value

        if kind == "paren" and value == "(":
            self._consume()

            if self._peek_value() == ")":
                raise ValueError("empty parentheses")

            inner = self.parse_expression()

            if self._peek_value() != ")":
                raise ValueError("missing closing parenthesis")

            self._consume()
            return inner

        if kind == "paren" and value == ")":
            raise ValueError("unbalanced parenthesis")

        raise ValueError(f"unexpected token {value!r}")


def _tokenize(expr: str):
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        ch = expr[i]

        if ch.isspace():
            i += 1
            continue

        if ch.isdigit() or ch == ".":
            start = i
            has_digit = False

            while i < n and expr[i].isdigit():
                has_digit = True
                i += 1

            if i < n and expr[i] == ".":
                i += 1
                while i < n and expr[i].isdigit():
                    has_digit = True
                    i += 1

            if not has_digit:
                raise ValueError("invalid numeric literal")

            literal = expr[start:i]
            try:
                tokens.append(("num", float(literal)))
            except OverflowError as exc:
                raise ValueError("numeric literal too large") from exc

            continue

        if ch == "(":
            tokens.append(("paren", "("))
            i += 1
            continue

        if ch == ")":
            tokens.append(("paren", ")"))
            i += 1
            continue

        if ch == "+":
            tokens.append(("op", "+"))
            i += 1
            continue

        if ch == "-":
            tokens.append(("op", "-"))
            i += 1
            continue

        if ch == "/":
            tokens.append(("op", "/"))
            i += 1
            continue

        if ch == "*":
            i += 1

            j = i
            while j < n and expr[j].isspace():
                j += 1

            if j < n and expr[j] == "*":
                tokens.append(("op", "**"))
                i = j + 1
            else:
                tokens.append(("op", "*"))

            continue

        raise ValueError(f"unknown character {ch!r}")

    return tokens


def _power(base: float, exponent: float) -> float:
    try:
        value = base ** exponent

        if isinstance(value, complex):
            if value.imag == 0:
                return float(value.real)
            raise ValueError("negative base raised to a non-integer exponent")

        if isinstance(value, float):
            return value

        return float(value)
    except OverflowError:
        raise
    except ZeroDivisionError:
        raise
    except ValueError:
        raise
    except TypeError as exc:
        raise ValueError("invalid exponentiation") from exc
