class Calendar:
    def __init__(self):
        self.intervals = []

    def book(self, start: int, end: int) -> bool:
        # Empty half-open interval covers no moment.
        if start >= end:
            return True

        # Sweep only the region where the new booking could matter.
        # Each key is a time point, each value is the net change in
        # covered intervals starting at that point.
        deltas = {
            start: 1,
            end: -1,
        }

        for a, b in self.intervals:
            # Half-open intervals overlap iff a < end and b > start.
            if a < end and b > start:
                s = max(a, start)
                e = min(b, end)
                if s < e:
                    deltas[s] = deltas.get(s, 0) + 1
                    deltas[e] = deltas.get(e, 0) - 1

        active = 0
        for point in sorted(deltas):
            active += deltas[point]
            if active >= 3:
                return False

        self.intervals.append((start, end))
        return True
