def evaluate(expr: str) -> float:
    # Tokenize without eval/exec/compile/ast
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        c = expr[i]

        if c.isspace():
            i += 1
            continue

        # Non-negative integer or decimal literal.
        # Python-style decimal forms: 3, 3.0, .5, 0.25.
        if c.isdigit() or (c == "." and i + 1 < n and expr[i + 1].isdigit()):
            start = i

            while i < n and expr[i].isdigit():
                i += 1

            if i < n and expr[i] == ".":
                i += 1
                while i < n and expr[i].isdigit():
                    i += 1

            literal = expr[start:i]

            if literal == ".":
                raise ValueError("malformed numeric literal")

            value = float(literal) if "." in literal else int(literal)
            tokens.append(("number", value))
            continue

        if c == "(":
            tokens.append(("lparen", c))
            i += 1
            continue

        if c == ")":
            tokens.append(("rparen", c))
            i += 1
            continue

        if c == "*":
            if i + 1 < n and expr[i + 1] == "*":
                tokens.append(("**", "**"))
                i += 2
            else:
                tokens.append(("*", "*"))
                i += 1
            continue

        if c in "+-/":
            tokens.append((c, c))
            i += 1
            continue

        raise ValueError(f"unknown character: {c!r}")

    class Parser:
        def __init__(self):
            self.pos = 0
            self.token_count = len(tokens)

        def peek(self):
            if self.pos < self.token_count:
                return tokens[self.pos]
            return None

        def is_op(self, op: str) -> bool:
            token = self.peek()
            return token is not None and token[0] == op

        def parse(self) -> float:
            value = self.arithmetic()
            if self.pos != self.token_count:
                raise ValueError("unexpected trailing token")
            return float(value)

        def arithmetic(self):
            value = self.term()

            while self.is_op("+") or self.is_op("-"):
                op = self.peek()[0]
                self.pos += 1
                rhs = self.term()

                if op == "+":
                    value += rhs
                else:
                    value -= rhs

            return value

        def term(self):
            value = self.factor()

            while self.is_op("*") or self.is_op("/"):
                op = self.peek()[0]
                self.pos += 1
                rhs = self.factor()

                if op == "*":
                    value *= rhs
                else:
                    value /= rhs

            return value

        def factor(self):
            token = self.peek()

            if token is None:
                raise ValueError("unexpected end of input")

            kind = token[0]

            if kind == "+":
                self.pos += 1
                return +self.factor()

            if kind == "-":
                self.pos += 1
                return -self.factor()

            return self.power()

        def power(self):
            base = self.primary()

            if self.is_op("**"):
                self.pos += 1
                exponent = self.factor()
                return base ** exponent

            return base

        def primary(self):
            token = self.peek()

            if token is None:
                raise ValueError("unexpected end of input")

            kind = token[0]

            if kind == "number":
                self.pos += 1
                return token[1]

            if kind == "lparen":
                self.pos += 1
                value = self.arithmetic()

                if self.pos >= self.token_count or tokens[self.pos][0] != "rparen":
                    raise ValueError("unbalanced parentheses")

                self.pos += 1
                return value

            raise ValueError(f"unexpected token: {kind!r}")

    return Parser().parse()
