def evaluate(expr: str) -> float:
    """
    Evaluate a Python-like arithmetic expression without eval, exec, compile, or ast.

    Supported:
      - non-negative integer and decimal literals
      - binary +, -, *, /, **
      - unary + and -
      - parentheses
      - arbitrary whitespace

    Precedence/associativity match Python:
      - ** is right-associative and binds tighter than unary +/-.
      - Example: -2**2 == -4
      - Example: 2**3**2 == 512
      - Example: 2**-1 == 0.5

    Raises:
      - ZeroDivisionError for division by zero
      - ValueError for malformed expressions
    """

    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    class Token:
        def __init__(self, kind: str, value: str):
            self.kind = kind
            self.value = value

        def __repr__(self):
            return f"Token({self.kind}, {self.value!r})"

    def tokenize(s: str):
        tokens = []
        i = 0
        n = len(s)

        while i < n:
            ch = s[i]

            if ch.isspace():
                i += 1
                continue

            if ch == "(":
                tokens.append(Token("LPAREN", "("))
                i += 1
                continue

            if ch == ")":
                tokens.append(Token("RPAREN", ")"))
                i += 1
                continue

            if ch == "+":
                tokens.append(Token("PLUS", "+"))
                i += 1
                continue

            if ch == "-":
                tokens.append(Token("MINUS", "-"))
                i += 1
                continue

            if ch == "*":
                if i + 1 < n and s[i + 1] == "*":
                    tokens.append(Token("POWER", "**"))
                    i += 2
                else:
                    tokens.append(Token("MUL", "*"))
                    i += 1
                continue

            if ch == "/":
                tokens.append(Token("DIV", "/"))
                i += 1
                continue

            if ch == ".":
                # Decimal literal beginning with a dot, e.g. .25
                if i + 1 < n and s[i + 1].isdigit():
                    start = i
                    i += 1
                    while i < n and s[i].isdigit():
                        i += 1
                    tokens.append(Token("NUMBER", s[start:i]))
                    continue
                raise ValueError("unknown character '.'")

            if ch.isdigit():
                start = i

                while i < n and s[i].isdigit():
                    i += 1

                if i < n and s[i] == ".":
                    i += 1
                    if i < n and s[i].isdigit():
                        while i < n and s[i].isdigit():
                            i += 1
                    # Allow forms like 3. as a valid decimal literal.

                tokens.append(Token("NUMBER", s[start:i]))
                continue

            raise ValueError(f"unknown character {ch!r}")

        return tokens

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None

        def consume(self, kind: str):
            tok = self.peek()
            if tok is None or tok.kind != kind:
                raise ValueError("malformed expression")
            self.pos += 1
            return tok

        # Operator precedence.
        # Higher number means tighter binding.
        # Unary precedence is between ** and multiplication.
        P_ADD_SUB = 10
        P_MUL_DIV = 20
        P_UNARY = 30
        P_POWER_LEFT = 40
        P_POWER_RIGHT = 30

        def parse_expression(self, min_precedence: int = 0) -> float:
            left = self.parse_prefix()

            while True:
                tok = self.peek()
                if tok is None:
                    break

                if tok.kind in ("PLUS", "MINUS"):
                    prec = self.P_ADD_SUB
                    if prec < min_precedence:
                        break
                    self.pos += 1
                    right = self.parse_expression(prec + 1)
                    if tok.kind == "PLUS":
                        left = left + right
                    else:
                        left = left - right
                    continue

                if tok.kind in ("MUL", "DIV"):
                    prec = self.P_MUL_DIV
                    if prec < min_precedence:
                        break
                    self.pos += 1
                    right = self.parse_expression(prec + 1)
                    if tok.kind == "MUL":
                        left = left * right
                    else:
                        if right == 0.0:
                            raise ZeroDivisionError("division by zero")
                        left = left / right
                    continue

                if tok.kind == "POWER":
                    prec = self.P_POWER_LEFT
                    if prec < min_precedence:
                        break
                    self.pos += 1

                    # ** is right-associative.
                    # The right operand is parsed at a precedence allowing
                    # another ** to bind to it.
                    right = self.parse_expression(self.P_POWER_RIGHT)
                    left = self._pow(left, right)
                    continue

                break

            return left

        def parse_prefix(self) -> float:
            tok = self.peek()
            if tok is None:
                raise ValueError("malformed expression")

            if tok.kind == "PLUS":
                self.pos += 1
                operand = self.parse_expression(self.P_UNARY)
                return +operand

            if tok.kind == "MINUS":
                self.pos += 1
                operand = self.parse_expression(self.P_UNARY)
                return -operand

            if tok.kind == "NUMBER":
                self.pos += 1
                try:
                    value = float(tok.value)
                except ValueError as exc:
                    raise ValueError("malformed numeric literal") from exc
                return value

            if tok.kind == "LPAREN":
                self.pos += 1
                value = self.parse_expression(0)
                self.consume("RPAREN")
                return value

            raise ValueError("malformed expression")

        @staticmethod
        def _pow(base: float, exponent: float) -> float:
            # Match Python's behavior for finite floating-point exponentiation.
            # For the cases relevant to normal decimal inputs, simple pow is enough.
            # Negative bases with fractional exponents raise ZeroDivisionError? No,
            # Python raises ValueError/complex issues; here keep native pow behavior.
            try:
                return float(base ** exponent)
            except ZeroDivisionError:
                raise ZeroDivisionError("division by zero")
            except OverflowError:
                raise ValueError("overflow")
            except ValueError:
                raise ValueError("invalid operation")

    def ensure_well_formed(tokens):
        if not tokens:
            raise ValueError("empty expression")

        if tokens[0].kind == "RPAREN":
            raise ValueError("unbalanced parentheses")

        if tokens[-1].kind in ("PLUS", "MINUS", "MUL", "DIV", "POWER", "LPAREN"):
            raise ValueError("dangling operator or unbalanced parentheses")

        balance = 0
        for tok in tokens:
            if tok.kind == "LPAREN":
                balance += 1
            elif tok.kind == "RPAREN":
                balance -= 1
                if balance < 0:
                    raise ValueError("unbalanced parentheses")
        if balance != 0:
            raise ValueError("unbalanced parentheses")

        prev = None
        for tok in tokens:
            if prev is not None:
                # Two values in a row.
                if prev.kind == "NUMBER" and tok.kind == "NUMBER":
                    raise ValueError("two numbers in a row")
                if prev.kind == "RPAREN" and tok.kind == "NUMBER":
                    raise ValueError("two numbers in a row")
                if prev.kind == "NUMBER" and tok.kind == "LPAREN":
                    raise ValueError("two numbers in a row")
                if prev.kind == "RPAREN" and tok.kind == "LPAREN":
                    raise ValueError("two numbers in a row")

            # Empty parentheses are detected separately.
            prev = tok

        # Empty parentheses: () or (whitespace)().
        for i in range(len(tokens) - 1):
            if tokens[i].kind == "LPAREN" and tokens[i + 1].kind == "RPAREN":
                raise ValueError("empty parentheses")

    tokens = tokenize(expr)
    ensure_well_formed(tokens)

    parser = Parser(tokens)
    result = parser.parse_expression(0)

    if parser.pos != len(tokens):
        raise ValueError("trailing input")

    return float(result)
